// ratelimit/limiter.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock is an injectable time source for deterministic testing.
type Clock interface {
	Now() time.Time
}

// Limiter is a concurrency-safe token-bucket rate limiter.
type Limiter struct {
	mu       sync.Mutex
	capacity float64
	rate     float64 // tokens per second
	tokens   float64
	last     time.Time
	clock    Clock
}

// NewLimiter creates a Limiter with the given capacity and refill rate (tokens/sec).
// The bucket starts full. Returns an error if capacity or rate are non-positive,
// or if clock is nil.
func NewLimiter(capacity, rate float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be positive")
	}
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be positive")
	}
	if clock == nil {
		return nil, errors.New("ratelimit: clock must not be nil")
	}
	return &Limiter{
		capacity: capacity,
		rate:     rate,
		tokens:   capacity,
		last:     clock.Now(),
		clock:    clock,
	}, nil
}

// AllowN attempts to consume n tokens. Returns true if the bucket had enough
// tokens, false otherwise. n must be positive.
func (l *Limiter) AllowN(n int) bool {
	if n <= 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.capacity {
			l.tokens = l.capacity
		}
		l.last = now
	}

	if l.tokens >= float64(n) {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Allow is a convenience wrapper for AllowN(1).
func (l *Limiter) Allow() bool {
	return l.AllowN(1)
}
