func TestNewLimiter_Validation(t *testing.T) {
	fc := &fakeClock{t: time.Now()}
	tests := []struct {
		name     string
		capacity float64
		rate     float64
		clock    Clock
		wantErr  bool
	}{
		{"valid", 10, 1, fc, false},
		{"zero capacity", 0, 1, fc, true},
