		name     string
		capacity float64
		rate     float64
		advances []time.Duration
		n        int
		want     []bool
	}{
		{
			name:     "burst then drain",
			capacity: 5,
			rate:     1,
			advances: []time.Duration{0, 0, 0, 0, 0, 0},
