			rate:     1,
			advances: []time.Duration{0, 0, 0, 0, 2 * time.Second, 0},
			n:        1,
			want:     []bool{true, true, true, false, true, true},
		},
		{
			name:     "allowN consumes multiple",
			capacity: 10,
			rate:     2,
			advances: []time.Duration{0, 0, 3 * time.Second, 0},
			n:        4,
			want:     []bool{true, true, true, false},
		},
		{
			name:     "n exceeds capacity always false",
			capacity: 5,
			rate:     10,
			advances: []time.Duration{0, 10 * time.Second},
			n:        6,
			want:     []bool{false, false},
		},
		{
			name:     "n zero or negative",
			capacity: 5,
			rate:     1,
			advances: []time.Duration{0, 0},
			n:        0,
			want:     []bool{false, false},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			fc := &fakeClock{t: time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)}
			lim, err := NewLimiter(tt.capacity, tt.rate, fc)
			if err != nil {
				t.Fatal(err)
			}
			for i, adv := range tt.advances {
				fc.Advance(adv)
				got := lim.AllowN(tt.n)
				if got != tt.want[i] {
					t.Errorf("call %d: got %v, want %v", i, got, tt.want[i])
				}
			}
		})
	}
}

func TestAllowN_Concurrent(t *testing.T) {
	fc := &fakeClock{t: time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)}
	lim, err := NewLimiter(100, 10, fc)
	if err != nil {
		t.Fatal(err)
	}
	const goroutines = 50
	const calls = 20
	done := make(chan bool, goroutines)
	for i := 0; i < goroutines; i++ {
		go func() {
			for j := 0; j < calls; j++ {
				lim.AllowN(1)
			}
			done <- true
		}()
	}
	for i := 0; i < goroutines; i++ {
		<-done
	}
}
