package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock provides the current time, enabling deterministic testing.
type Clock interface {
	Now() time.Time
}

// TokenBucket is a concurrency-safe token-bucket rate limiter.
type TokenBucket struct {
	mu       sync.Mutex
	capacity float64
	rate     float64 // tokens per second
	tokens   float64
	last     time.Time
	clock    Clock
}

// NewTokenBucket creates a TokenBucket with the given capacity (max burst),
// refill rate (tokens per second), and clock. Returns an error if parameters
// are invalid.
func NewTokenBucket(capacity, rate float64, clock Clock) (*TokenBucket, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: clock must not be nil")
	}
	if capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be positive")
	}
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be positive")
	}
	return &TokenBucket{
		capacity: capacity,
		rate:     rate,
		tokens:   capacity,
		last:     clock.Now(),
		clock:    clock,
	}, nil
}

// AllowN reports whether n tokens are available and consumes them if so.
// n must be positive.
func (tb *TokenBucket) AllowN(n int) bool {
	if n <= 0 {
		return false
	}
	tb.mu.Lock()
	defer tb.mu.Unlock()

	now := tb.clock.Now()
	elapsed := now.Sub(tb.last).Seconds()
	tb.last = now

	tb.tokens += elapsed * tb.rate
	if tb.tokens > tb.capacity {
		tb.tokens = tb.capacity
	}

	if tb.tokens >= float64(n) {
		tb.tokens -= float64(n)
		return true
	}
	return false
}

// Allow is shorthand for AllowN(1).
func (tb *TokenBucket) Allow() bool {
	return tb.AllowN(1)
}
